package conformance
import("bytes";"encoding/json";"fmt";"math";"strconv";"github.com/kakon77777-commits/isql-origin-go/sections";"github.com/kakon77777-commits/isql-origin-go/wire")
type HolonomyReport struct{Status string;Final []byte;StepCount int}
type harnessDef struct{Schema string `json:"schema"`;Transformers map[string]struct{Op string `json:"op"`;Arg int `json:"arg"`} `json:"transformers"`;Observables map[string]struct{Op string `json:"op"`} `json:"observables"`;Comparators map[string]struct{Op string `json:"op"`} `json:"comparators"`;Tolerances map[string]float64 `json:"tolerances"`}
func refText(r wire.Ref)string{return fmt.Sprintf("%d:%d",r.BundleSlot,r.LocalID)};func hasRef(xs []wire.Ref,r wire.Ref)bool{for _,x:=range xs{if x==r{return true}};return false}
func RunHolonomy(obj wire.OMIR,harnessJSON,payload []byte,path []wire.Ref,invariant wire.Ref)(HolonomyReport,error){var h harnessDef;if err:=json.Unmarshal(harnessJSON,&h);err!=nil{return HolonomyReport{},err};if h.Schema!="isql-origin-p2-reference-harness/v0.3"{return HolonomyReport{},fmt.Errorf("P2_HARNESS_SCHEMA_INVALID")};by:=sectionMap(obj);charts,err:=sections.DecodeSemanticCharts(by[2]);if err!=nil{return HolonomyReport{},err};trans,err:=sections.DecodeTransitions(by[3]);if err!=nil{return HolonomyReport{},err};invs,err:=sections.DecodeInvariantContracts(by[8]);if err!=nil{return HolonomyReport{},err};cm:=map[wire.Ref]bool{};for _,c:=range charts{cm[c.Chart]=true};tm:=map[wire.Ref]sections.Transition{};for _,t:=range trans{tm[t.Transition]=t};im:=map[wire.Ref]sections.InvariantContract{};for _,iv:=range invs{im[iv.Invariant]=iv};if len(path)==0{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_PATH_EMPTY")};first,ok:=tm[path[0]];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TRANSITION_UNKNOWN")};if !cm[first.SourceChart]{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_CHART_UNKNOWN")};currentChart:=first.SourceChart;data:=append([]byte(nil),payload...);for _,pr:=range path{tr,ok:=tm[pr];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TRANSITION_UNKNOWN")};if tr.SourceChart!=currentChart{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_PATH_DISCONTINUITY")};if !tr.Deterministic{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_NONDETERMINISTIC")};if !hasRef(tr.Preserved,invariant){return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_INVARIANT_NOT_PRESERVED")};def,ok:=h.Transformers[refText(tr.Transformer)];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TRANSFORMER_UNBOUND")};switch def.Op{case "identity":case "int-add":n,e:=strconv.Atoi(string(data));if e!=nil{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_INT_INVALID")};data=[]byte(strconv.Itoa(n+def.Arg));default:return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TRANSFORMER_UNKNOWN")};currentChart=tr.TargetChart};if currentChart!=first.SourceChart{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_PATH_NOT_CLOSED")};iv,ok:=im[invariant];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_INVARIANT_UNKNOWN")};if len(iv.Observables)==0{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_OBSERVABLE_MISSING")};obsDef,ok:=h.Observables[refText(iv.Observables[0])];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_OBSERVABLE_UNBOUND")};cmpDef,ok:=h.Comparators[refText(iv.Comparator)];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_COMPARATOR_UNBOUND")};pass:=false;switch cmpDef.Op{case "exact":if obsDef.Op!="bytes"{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_OBSERVABLE_INVALID")};pass=bytes.Equal(payload,data);case "numeric-abs":if obsDef.Op!="int"{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_OBSERVABLE_INVALID")};a,e:=strconv.Atoi(string(payload));if e!=nil{return HolonomyReport{},e};b,e:=strconv.Atoi(string(data));if e!=nil{return HolonomyReport{},e};if iv.Tolerance==nil{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TOLERANCE_MISSING")};tol,ok:=h.Tolerances[refText(*iv.Tolerance)];if !ok{return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_TOLERANCE_UNBOUND")};pass=math.Abs(float64(a-b))<=tol;default:return HolonomyReport{},fmt.Errorf("P2_HOLONOMY_COMPARATOR_UNKNOWN")};status:="drift";if pass{if bytes.Equal(payload,data){status="exact"}else{status="within_tolerance"}};return HolonomyReport{Status:status,Final:data,StepCount:len(path)},nil}
